import React from "react";
import { graphql, Link, type HeadFC } from "gatsby";
import { useTranslation } from "gatsby-plugin-react-i18next";
import Layout from "../components/Layout";
import SEO from "../components/seo";

const ProcessPage: React.FC = () => {
  const { t } = useTranslation("process");

  const steps = [
    { n: "01", title: t("step1Title"), time: t("step1Time"), sub: t("step1Sub"), detail: t("step1Detail"), badge: t("step1Badge"), color: "var(--blue)" },
    { n: "02", title: t("step2Title"), time: t("step2Time"), sub: t("step2Sub"), detail: t("step2Detail"), badge: t("step2Badge"), color: "var(--blue)" },
    { n: "03", title: t("step3Title"), time: t("step3Time"), sub: t("step3Sub"), detail: t("step3Detail"), badge: t("step3Badge"), color: "var(--cyan)" },
    { n: "04", title: t("step4Title"), time: t("step4Time"), sub: t("step4Sub"), detail: t("step4Detail"), badge: t("step4Badge"), color: "var(--green)" },
    { n: "05", title: t("step5Title"), time: t("step5Time"), sub: t("step5Sub"), detail: t("step5Detail"), badge: t("step5Badge"), color: "var(--amber)" },
  ];

  return (
    <Layout activeNav="process">
      <div style={{ paddingTop: "var(--space-10)", paddingBottom: "var(--space-10)" }}>
        <div className="cc-container" style={{ paddingTop: "var(--space-8)" }}>
          <div className="section-label">
            <span className="num">00</span>
            <span className="rule" />
            <span className="name">{t("sectionName")}</span>
          </div>
          <h1 className="text-h1" style={{ maxWidth: 640 }}>{t("title")}</h1>
          <p className="text-lg-body" style={{ maxWidth: 560, marginTop: "var(--space-4)" }}>{t("sub")}</p>
        </div>

        <div className="section-divider cc-container" />

        <div className="cc-container">
          <div className="flex flex-col gap-0">
            {steps.map((step, i) => (
              <div key={step.n} className="flex gap-8 md:gap-16">
                {/* Timeline */}
                <div className="flex flex-col items-center" style={{ flexShrink: 0, width: 56 }}>
                  <div style={{
                    width: 44, height: 44, background: "var(--bg-card)", border: `2px solid ${step.color}`,
                    borderRadius: "50%", display: "flex", alignItems: "center", justifyContent: "center",
                    boxShadow: `0 0 20px ${step.color}44`, flexShrink: 0,
                  }}>
                    <span style={{ fontFamily: "'JetBrains Mono',monospace", fontSize: 12, fontWeight: 500, color: step.color }}>{step.n}</span>
                  </div>
                  {i < steps.length - 1 && (
                    <div style={{ width: 1, flex: 1, minHeight: 48, background: "var(--border-1)", margin: "8px 0" }} />
                  )}
                </div>

                {/* Content */}
                <div style={{ paddingBottom: i < steps.length - 1 ? "var(--space-8)" : 0, paddingTop: 8 }}>
                  <div className="flex flex-wrap items-center gap-3">
                    <h2 className="text-h2">{step.title}</h2>
                    <span className="cc-badge cc-badge-cyan">{step.badge}</span>
                    <span className="text-sm-body">{step.time}</span>
                  </div>
                  <p className="text-lg-body mt-3">{step.sub}</p>
                  <p className="text-base-body mt-2">{step.detail}</p>
                </div>
              </div>
            ))}
          </div>

          {/* Pricing note */}
          <div style={{
            marginTop: "var(--space-10)", padding: "var(--space-7)",
            background: "var(--bg-surface)", border: "1px solid var(--border-2)",
            borderRadius: "var(--radius-lg)",
          }}>
            <h3 className="text-h2">{t("pricingTitle")}</h3>
            <p className="text-lg-body mt-3">{t("pricingSub")}</p>
            <div className="grid grid-cols-2 md:grid-cols-4 gap-6 mt-6">
              {(t("pricingTiers", { returnObjects: true }) as Array<{ range: string; label: string; desc: string }>).map((tier) => (
                <div key={tier.range}>
                  <div style={{ fontFamily: "'Sora',sans-serif", fontSize: 22, fontWeight: 700, color: "var(--text-1)" }}>{tier.range}</div>
                  <div className="text-mono mt-1">{tier.label}</div>
                  <p className="text-sm-body mt-2">{tier.desc}</p>
                </div>
              ))}
            </div>
          </div>

          {/* CTA */}
          <div style={{ textAlign: "center", marginTop: "var(--space-9)" }}>
            <Link to="/contact/" className="btn-primary">
              {t("ctaBtn")}
              <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round"><path d="M5 12h14M12 5l7 7-7 7" /></svg>
            </Link>
          </div>
        </div>
      </div>
    </Layout>
  );
};

export default ProcessPage;

export const Head: HeadFC = ({ data, location }: any) => (
  <SEO
    data={data.allDataJson.nodes[0]}
    title="Process - Code Crafted"
    description="Five phases, fixed scope, no surprises. Discovery, scoping, build, deploy, support. Transparent process for custom business application development."
    language={data.locales?.edges?.[0]?.node?.language}
    originalPath={location.pathname}
    pageSchemaType="WebPage"
    schemaType="ProfessionalService"
  />
);

export const query = graphql`
  query ($language: String!) {
    locales: allLocale(filter: { language: { eq: $language } }) {
      edges { node { ns data language } }
    }
    allDataJson {
      nodes {
        companyName address city province country postalCode
        phone email instagram facebook linkedin whatsapp url
        founder { name jobTitle sameAs }
      }
    }
  }
`;
